    .filter(Boolean);
}

export function parse(markdown) {
  const lines = markdown.split(/\r?\n/);
  const start = lines.findIndex((l) => /^\|\s*Product name\s*\|\s*String ID\s*\|\s*GUID\s*\|\s*Service plans included\s*\|/i.test(l));
  if (start < 0) throw new Error("The product table was not found. The page layout may have changed.");
  const products = [];
  const plans = new Map();
  let skipped = 0;
  // The table rows follow the header and its separator line, up to the first line that is not a row.
  for (const line of lines.slice(start + 2)) {
    if (!line.trim().startsWith("|")) break;
    const row = cells(line);
    if (row.length < 5) continue;
    const [name, stringId, guid, included, friendly] = row;
    const productIndex = products.length;
    products.push([name, stringId.replace(/\s+/g, ""), guid.toLowerCase()]);
    const friendlyByGuid = new Map(entries(friendly).map((e) => [e.guid, e.name]));
    for (const entry of entries(included)) {
      // The page has stray spaces inside some names ("Auditing_10Year_ Retention_ Add_On").
      const plan = entry.name.replace(/\s+/g, "");
      if (!TOKEN.test(plan)) {
        skipped++;
        continue;
      }
      const key = plan.toUpperCase();
      if (!plans.has(key)) plans.set(key, { name: plan, guids: new Set(), friendly: "", products: new Set() });
      const record = plans.get(key);
      record.guids.add(entry.guid);
      if (!record.friendly && friendlyByGuid.get(entry.guid)) record.friendly = friendlyByGuid.get(entry.guid);
      record.products.add(productIndex);
    }
  }
  if (products.length < 100 || plans.size < 100) throw new Error(`Only ${products.length} products and ${plans.size} plans were parsed. Refusing to write.`);
  return {
    note: "Generated by website/scripts/update-license-service-plans.mjs from " + SOURCE_URL + ". Do not edit.",
    // [product name, string ID, GUID]
    products,
    // [service plan name, friendly name, GUIDs, indexes into products]
    plans: [...plans.values()].sort((a, b) => a.name.localeCompare(b.name, "en")).map((p) => [p.name, p.friendly, [...p.guids].sort(), [...p.products]]),
    skipped,
  };
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const markdown = await (await fetch(SOURCE_URL)).text();
  const data = parse(markdown);
  const { skipped, ...output } = data;
  const target = path.join(path.dirname(fileURLToPath(import.meta.url)), "..", "src", "data", "license-service-plans.json");
  await writeFile(target, JSON.stringify(output) + "\n");
  console.log(`Wrote ${output.products.length} products and ${output.plans.length} service plans to ${path.relative(process.cwd(), target)}. Skipped ${skipped} plan entries with unusable names.`);
}
name: update-license-service-plans

# Keeps the licence lookup of the test builder (maester.dev/test-builder) in step with Microsoft's
# "Product names and service plan identifiers for licensing" page.

on:
  workflow_dispatch:
  schedule:
    - cron: '41 5 * * *'

permissions: {}

concurrency:
  group: update-license-service-plans
  cancel-in-progress: false

jobs:
  update-license-service-plans:
    runs-on: ubuntu-latest
    permissions:
      contents: read

    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          persist-credentials: false

      - name: Download and parse the licensing reference
        working-directory: website
        run: node scripts/update-license-service-plans.mjs

      - name: Generate maester-bot app token
        id: app-token
        uses: actions/create-github-app-token@64ab729a6294000f5aa4a4bc0b73d1f32bc45510 # v3.3.0
        with:
          app-id: ${{ secrets.MAESTER_BOT_APP_ID }}
          private-key: ${{ secrets.MAESTER_BOT_PRIVATE_KEY }}
          permission-contents: write
          permission-pull-requests: write

      - name: Create Pull Request
        uses: peter-evans/create-pull-request@5f6978faf089d4d20b00c7766989d076bb2fc7f1 # v8.1.1
        with:
          token: ${{ steps.app-token.outputs.token }}
          add-paths: website/src/data/license-service-plans.json
          commit-message: 'chore: update licence service plans'
          branch: 'automation/update-license-service-plans'
          delete-branch: true
          title: 'chore: update licence service plans'
          body: |
            Refreshes `website/src/data/license-service-plans.json` from Microsoft's licensing reference:
            https://learn.microsoft.com/entra/identity/users/licensing-service-plan-reference

            The file is parsed from the page's Markdown in `MicrosoftDocs/entra-docs` by `website/scripts/update-license-service-plans.mjs`.

            Why this matters in Maester:
            - The test builder at maester.dev/test-builder uses this list to look up the service plan names for `[MaesterTest(License = ...)]`.
            - Nothing in the module reads this file. A test's licence check matches the plan name against the tenant at run time.

            Reviewer note:
            - A diff that removes many plans at once probably means the page layout changed. The script refuses to write when it parses fewer than 100 products or plans.

